WITH filtered AS (SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, SUBSTRING(city, 1, 2) AS city_prefix, COALESCE(city, 'N/A') AS city_clean FROM customers WHERE signup_date BETWEEN '2023-11-01' AND '2025-04-01') SELECT *, CUME_DIST() OVER (PARTITION BY city ORDER BY credit_limit) AS credit_limit_cume_dist, SUM(credit_limit) OVER (ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_credit_limit, ROW_NUMBER() OVER (ORDER BY credit_limit DESC, id) AS seq_no FROM filtered
